  const taskId = e.payload?.taskId ?? e.payload?.id;
  if (e.type === 'humanTask.answered') {
    const ans = e.payload?.answer ?? e.payload ?? {};
    const ok = (ans.decision === 'approve' || ans.decision === 'reject') && (!taskId || taskId === rv.taskId);
